plaintext__rev_rune_string = "ᛏᚻᛖᚱᛖ ᚹᚪᛋ ᚪ ᛏᚪᛒᛚᛖ ᛋᛖᛏ ᚩᚢᛏ ᚢᚾᛞᛖᚱ ᚪ ᛏᚱᛖᛖ ᛁᚾ ᚠᚱᚩᚾᛏ ᚩᚠ ᛏᚻᛖ ᚻᚩᚢᛋᛖ ᚪᚾᛞ ᛏᚻᛖ ᛗᚪᚱᚳᚻ ᚻᚪᚱᛖ ᚪᚾᛞ ᛏᚻᛖ ᚻᚪᛏᛏᛖᚱ ᚹᛖᚱᛖ ᚻᚪᚢᛁᚾᚷ ᛏᚫ ᚪᛏ ᛁᛏ ᚪ ᛞᚩᚱᛗᚩᚢᛋᛖ ᚹᚪᛋ ᛋᛁᛏᛏᛁᚾᚷ ᛒᛖᛏᚹᛖᛖᚾ ᛏᚻᛖᛗ ᚠᚪᛋᛏ ᚪᛋᛚᛖᛖᛈ ᚪᚾᛞ ᛏᚻᛖ ᚩᛏᚻᛖᚱ ᛏᚹᚩ ᚹᛖᚱᛖ ᚢᛋᛁᚾᚷ ᛁᛏ ᚪᛋ ᚪ ᚳᚢᛋᚻᛁᚩᚾ ᚱᛖᛋᛏᛁᚾᚷ ᛏᚻᛖᛁᚱ ᛖᛚᛒᚩᚹᛋ ᚩᚾ ᛁᛏ ᚪᚾᛞ ᛏᚪᛚᚳᛁᚾᚷ ᚩᚢᛖᚱ ᛁᛏᛋ ᚻᚫᛞ ᚢᛖᚱᚣ ᚢᚾᚳᚩᛗᚠᚩᚱᛏᚪᛒᛚᛖ ᚠᚩᚱ ᛏᚻᛖ ᛞᚩᚱᛗᚩᚢᛋᛖ ᛏᚻᚩᚢᚷᚦ ᚪᛚᛁᚳᛖ ᚩᚾᛚᚣ ᚪᛋ ᛁᛏᛋ ᚪᛋᛚᛖᛖᛈ ᛁ ᛋᚢᛈᛈᚩᛋᛖ ᛁᛏ ᛞᛇᛋᚾᛏ ᛗᛁᚾᛞ ᛏᚻᛖ ᛏᚪᛒᛚᛖ ᚹᚪᛋ ᚪ ᛚᚪᚱᚷᛖ ᚩᚾᛖ ᛒᚢᛏ ᛏᚻᛖ ᛏᚻᚱᛖᛖ ᚹᛖᚱᛖ ᚪᛚᛚ ᚳᚱᚩᚹᛞᛖᛞ ᛏᚩᚷᛖᛏᚻᛖᚱ ᚪᛏ ᚩᚾᛖ ᚳᚩᚱᚾᛖᚱ ᚩᚠ ᛁᛏ ᚾᚩ ᚱᚩᚩᛗ ᚾᚩ ᚱᚩᚩᛗ ᛏᚻᛖᚣ ᚳᚱᛁᛖᛞ ᚩᚢᛏ ᚹᚻᛖᚾ ᛏᚻᛖᚣ ᛋᚪᚹ ᚪᛚᛁᚳᛖ ᚳᚩᛗᛁᚾᚷ ᛏᚻᛖᚱᛖᛋ ᛈᛚᛖᚾᛏᚣ ᚩᚠ ᚱᚩᚩᛗ ᛋᛡᛞ ᚪᛚᛁᚳᛖ ᛁᚾᛞᛁᛝᚪᚾᛏᛚᚣ ᚪᚾᛞ ᛋᚻᛖ ᛋᚪᛏ ᛞᚩᚹᚾ ᛁᚾ ᚪ ᛚᚪᚱᚷᛖ ᚪᚱᛗ ᚳᚻᛡᚱ ᚪᛏ ᚩᚾᛖ ᛖᚾᛞ ᚩᚠ ᛏᚻᛖ ᛏᚪᛒᛚᛖ ᚻᚪᚢᛖ ᛋᚩᛗᛖ ᚹᛁᚾᛖ ᛏᚻᛖ ᛗᚪᚱᚳᚻ ᚻᚪᚱᛖ ᛋᛡᛞ ᛁᚾ ᚪᚾ ᛖᚾᚳᚩᚢᚱᚪᚷᛁᚾᚷ ᛏᚩᚾᛖ ᚪᛚᛁᚳᛖ ᛚᚩᚩᚳᛖᛞ ᚪᛚᛚ ᚱᚩᚢᚾᛞ ᛏᚻᛖ ᛏᚪᛒᛚᛖ ᛒᚢᛏ ᛏᚻᛖᚱᛖ ᚹᚪᛋ ᚾᚩᛏᚻᛁᚾᚷ ᚩᚾ ᛁᛏ ᛒᚢᛏ ᛏᚫ ᛁ ᛞᚩᚾᛏ ᛋᛖᛖ ᚪᚾᚣ ᚹᛁᚾᛖ ᛋᚻᛖ ᚱᛖᛗᚪᚱᚳᛖᛞ ᛏᚻᛖᚱᛖ ᛁᛋᚾᛏ ᚪᚾᚣ ᛋᛡᛞ ᛏᚻᛖ ᛗᚪᚱᚳᚻ ᚻᚪᚱᛖ ᛏᚻᛖᚾ ᛁᛏ ᚹᚪᛋᚾᛏ ᚢᛖᚱᚣ ᚳᛁᚢᛁᛚ ᚩᚠ ᚣᚩᚢ ᛏᚩ ᚩᚠᚠᛖᚱ ᛁᛏ ᛋᛡᛞ ᚪᛚᛁᚳᛖ ᚪᚾᚷᚱᛁᛚᚣ ᛁᛏ ᚹᚪᛋᚾᛏ ᚢᛖᚱᚣ ᚳᛁᚢᛁᛚ ᚩᚠ ᚣᚩᚢ ᛏᚩ ᛋᛁᛏ ᛞᚩᚹᚾ ᚹᛁᛏᚻᚩᚢᛏ ᛒᛖᛁᚾᚷ ᛁᚾᚢᛁᛏᛖᛞ ᛋᛡᛞ ᛏᚻᛖ ᛗᚪᚱᚳᚻ ᚻᚪᚱᛖ ᛁ ᛞᛁᛞᚾᛏ ᚳᚾᚩᚹ ᛁᛏ ᚹᚪᛋ ᚣᚩᚢᚱ ᛏᚪᛒᛚᛖ ᛋᛡᛞ ᚪᛚᛁᚳᛖ ᛁᛏᛋ ᛚᛡᛞ ᚠᚩᚱ ᚪ ᚷᚱᚫᛏ ᛗᚪᚾᚣ ᛗᚩᚱᛖ ᛏᚻᚪᚾ ᛏᚻᚱᛖᛖ ᚣᚩᚢᚱ ᚻᛡᚱ ᚹᚪᚾᛏᛋ ᚳᚢᛏᛏᛁᚾᚷ ᛋᛡᛞ ᛏᚻᛖ ᚻᚪᛏᛏᛖᚱ ᚻᛖ ᚻᚪᛞ ᛒᛖᛖᚾ ᛚᚩᚩᚳᛁᚾᚷ ᚪᛏ ᚪᛚᛁᚳᛖ ᚠᚩᚱ ᛋᚩᛗᛖ ᛏᛁᛗᛖ ᚹᛁᛏᚻ ᚷᚱᚫᛏ ᚳᚢᚱᛁᚩᛋᛁᛏᚣ ᚪᚾᛞ ᛏᚻᛁᛋ ᚹᚪᛋ ᚻᛁᛋ ᚠᛁᚱᛋᛏ ᛋᛈᛖᛖᚳᚻ ᚣᚩᚢ ᛋᚻᚩᚢᛚᛞ ᛚᚫᚱᚾ ᚾᚩᛏ ᛏᚩ ᛗᚪᚳᛖ ᛈᛖᚱᛋᚩᚾᚪᛚ ᚱᛖᛗᚪᚱᚳᛋ ᚪᛚᛁᚳᛖ ᛋᛡᛞ ᚹᛁᛏᚻ ᛋᚩᛗᛖ ᛋᛖᚢᛖᚱᛁᛏᚣ ᛁᛏᛋ ᚢᛖᚱᚣ ᚱᚢᛞᛖ ᛏᚻᛖ ᚻᚪᛏᛏᛖᚱ ᚩᛈᛖᚾᛖᛞ ᚻᛁᛋ ᛖᚣᛖᛋ ᚢᛖᚱᚣ ᚹᛁᛞᛖ ᚩᚾ ᚻᚫᚱᛁᚾᚷ ᛏᚻᛁᛋ ᛒᚢᛏ ᚪᛚᛚ ᚻᛖ ᛋᛡᛞ ᚹᚪᛋ ᚹᚻᚣ ᛁᛋ ᚪ ᚱᚪᚢᛖᚾ ᛚᛁᚳᛖ ᚪ ᚹᚱᛁᛏᛁᚾᚷ ᛞᛖᛋᚳ ᚳᚩᛗᛖ ᚹᛖ ᛋᚻᚪᛚᛚ ᚻᚪᚢᛖ ᛋᚩᛗᛖ ᚠᚢᚾ ᚾᚩᚹ ᛏᚻᚩᚢᚷᚦ ᚪᛚᛁᚳᛖ ᛁᛗ ᚷᛚᚪᛞ ᛏᚻᛖᚣᚢᛖ ᛒᛖᚷᚢᚾ ᚪᛋᚳᛁᚾᚷ ᚱᛁᛞᛞᛚᛖᛋ ᛁ ᛒᛖᛚᛁᛖᚢᛖ ᛁ ᚳᚪᚾ ᚷᚢᛖᛋᛋ ᛏᚻᚪᛏ ᛋᚻᛖ ᚪᛞᛞᛖᛞ ᚪᛚᚩᚢᛞ ᛞᚩ ᚣᚩᚢ ᛗᚫᚾ ᛏᚻᚪᛏ ᚣᚩᚢ ᛏᚻᛁᚾᚳ ᚣᚩᚢ ᚳᚪᚾ ᚠᛁᚾᛞ ᚩᚢᛏ ᛏᚻᛖ ᚪᚾᛋᚹᛖᚱ ᛏᚩ ᛁᛏ ᛋᛡᛞ ᛏᚻᛖ ᛗᚪᚱᚳᚻ ᚻᚪᚱᛖ  ᛖᛉᚪᚳᛏᛚᚣ ᛋᚩ ᛋᛡᛞ ᚪᛚᛁᚳᛖ"

plaintext_english_string = ("There was a table set out under a tree in front of the house and the March Hare and the Hatter were having tea at it a Dormouse was sitting between them fast asleep and the other two were using it as a cushion resting their elbows on it and talking over its head Very uncomfortable for the Dormouse thought Alice only as its asleep I suppose it doesnt mind The table was a large one but the three were all crowded together at one corner of it No room No room they cried out when they saw Alice coming Theres plenty of room said Alice indignantly and she sat down in a large arm chair at one end of the table Have some wine the March Hare said in an encouraging tone Alice looked all round the table but there was nothing on it but tea I dont see any wine she remarked There isnt any said the March Hare Then it wasnt very civil of you to offer it said Alice angrily It wasnt very civil of you to sit down without being invited said the March Hare I didnt know it was your table said Alice its laid for a great many more than three Your hair wants cutting said the Hatter He had been looking at Alice for some time with great curiosity and this was his first speech You should learn not to make personal remarks Alice said with some severity its very rude The Hatter opened his eyes very wide on hearing this but all he said was Why is a raven like a writing desk Come we shall have some fun now thought Alice Im glad theyve begun asking riddles I believe I can guess that she added aloud Do you mean that you think you can find out the answer to it said the March Hare Exactly so said Alice ")